public class PomPropertyResolverTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static java.util.Map<String, String> props() {
        java.util.Map<String, String> m = new java.util.HashMap<>();
        m.put("jackson.version", "2.15.2");
        m.put("junit.version", "5.10.0");
        m.put("lib.version", "${junit.version}");
        m.put("a", "${b}");
        m.put("b", "${a}");
        return m;
    }

    public static void main(String[] args) {
        java.util.Map<String, String> p = props();
        check("single placeholder", "jackson-databind-2.15.2",
                PomPropertyResolver.resolve("jackson-databind-${jackson.version}", p));
        check("two placeholders", "5.10.0 and 2.15.2",
                PomPropertyResolver.resolve("${junit.version} and ${jackson.version}", p));
        check("nested property", "5.10.0", PomPropertyResolver.resolve("${lib.version}", p));
        check("unknown key is left alone", "${no.such.key}",
                PomPropertyResolver.resolve("${no.such.key}", p));
        check("plain text is unchanged", "1.0.0", PomPropertyResolver.resolve("1.0.0", p));
        check("unclosed placeholder is left alone", "${oops",
                PomPropertyResolver.resolve("${oops", p));
        check("hasUnresolved on a resolvable text", false,
                PomPropertyResolver.hasUnresolved("${jackson.version}", p));
        check("hasUnresolved on an unknown key", true,
                PomPropertyResolver.hasUnresolved("v${no.such.key}", p));
        check("a cycle terminates and reports unresolved", true,
                PomPropertyResolver.hasUnresolved("${a}", p));
        finish();
    }
}

