public class PomPropertyResolver {

    public static String resolve(String text, java.util.Map<String, String> props) {
        String current = text;
        for (int pass = 0; pass < 10; pass++) {
            String next = expandOnce(current, props);
            if (next.equals(current)) {
                return current;
            }
            current = next;
        }
        return current;
    }

    public static boolean hasUnresolved(String text, java.util.Map<String, String> props) {
        return resolve(text, props).contains("${");
    }

    private static String expandOnce(String text, java.util.Map<String, String> props) {
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < text.length()) {
            int start = text.indexOf("${", i);
            if (start < 0) {
                out.append(text.substring(i));
                break;
            }
            int end = text.indexOf('}', start);
            if (end < 0) {
                out.append(text.substring(i));
                break;
            }
            out.append(text, i, start);
            String key = text.substring(start + 2, end);
            String value = props.get(key);
            if (value == null) {
                out.append(text, start, end + 1);
            } else {
                out.append(value);
            }
            i = end + 1;
        }
        return out.toString();
    }
}
